using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    while (cin >> n >> m) {
        unordered_map<string, vector<int>> dens;
        dens.reserve(n * 2);

        for (int i = 0; i < n; ++i) {
            string color;
            int d;
            cin >> color >> d;
            dens[color].push_back(d);
        }

        for (auto &p : dens) {
            auto &v = p.second;
            sort(v.begin(), v.end());
        }

        while (m--) {
            int k;
            cin >> k;
            vector<string> req(k);
            for (int i = 0; i < k; ++i) cin >> req[i];

            unordered_map<string, int> need;
            need.reserve(k * 2);
            for (auto &c : req) need[c]++;

            bool ok = true;
            vector<int> chosen;

            for (auto &p : need) {
                const string &color = p.first;
                int cnt = p.second;
                if (!dens.count(color) || (int)dens[color].size() < cnt) {
                    ok = false;
                    break;
                }
                auto &v = dens[color];
                for (int i = 0; i < cnt; ++i) chosen.push_back(v[i]);
            }

            if (!ok) {
                cout << "No\n";
                continue;
            }

            sort(chosen.begin(), chosen.end());
            if ((int)chosen.size() < k) {
                cout << "No\n";
                continue;
            }

            // Need k distinct densities to stack strictly by density.
            bool distinct = true;
            for (int i = 1; i < k; ++i) {
                if (chosen[i] == chosen[i - 1]) {
                    distinct = false;
                    break;
                }
            }

            cout << (distinct ? "Yes\n" : "No\n");
        }
    }

    return 0;
}

