public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        // Read number of available liquids
        int N = Integer.parseInt(br.readLine());
        List<Liquid> liquids = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            String color = st.nextToken();
            int density = Integer.parseInt(st.nextToken());
            liquids.add(new Liquid(color, density));
        }

        // Sort by density ascending
        liquids.sort(Comparator.comparingInt(l -> l.density));

        // Read number of drink requests
        int K = Integer.parseInt(br.readLine());
        List<String> results = new ArrayList<>();

        for (int i = 0; i < K; i++) {
            int L = Integer.parseInt(br.readLine());
            String[] request = new String[L];
            for (int j = 0; j < L; j++) {
                request[j] = br.readLine();
            }
            results.add(canMakeDrink(liquids, request) ? "Yes" : "No");
        }

        // Output results
        for (String res : results) {
            System.out.println(res);
        }
    }

    static boolean canMakeDrink(List<Liquid> liquids, String[] request) {
        int idx = 0; // pointer in sorted liquids
        for (String color : request) {
            // Find the next liquid with this color and strictly greater density than previous
            boolean found = false;
            while (idx < liquids.size()) {
                Liquid cur = liquids.get(idx);
                if (cur.color.equals(color)) {
                    found = true;
                    idx++; // move past used liquid
                    break;
                }
                idx++;
            }
            if (!found) return false;
        }
        return true;
    }

    static class Liquid {
        String color;
        int density;
        Liquid(String color, int density) {
            this.color = color;
            this.density = density;
        }
    }
}

