public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int N = sc.nextInt();
            int M = sc.nextInt();
            if (N == 0 && M == 0) break;

            Map<String, List<Double>> colorMap = new HashMap<>();
            for (int i = 0; i < N; i++) {
                String color = sc.next();
                double density = sc.nextDouble();
                colorMap.computeIfAbsent(color, k -> new ArrayList<>()).add(density);
            }

            // Sort each color's densities
            for (List<Double> list : colorMap.values()) {
                Collections.sort(list);
            }

            // Track current index in each color's sorted list
            Map<String, Integer> idx = new HashMap<>();

            String[] layers = new String[M];
            for (int i = 0; i < M; i++) layers[i] = sc.next();

            boolean possible = true;
            double prevDensity = Double.NEGATIVE_INFINITY;

            for (int i = 0; i < M; i++) {
                String color = layers[i];
                List<Double> densities = colorMap.get(color);
                if (densities == null) { possible = false; break; }

                int start = idx.getOrDefault(color, 0);
                // Find smallest density > prevDensity starting from start
                // Use binary search
                double target = prevDensity;
                int lo = start, hi = densities.size();
                while (lo < hi) {
                    int mid = (lo + hi) / 2;
                    if (densities.get(mid) <= target) lo = mid + 1;
                    else hi = mid;
                }
                if (lo >= densities.size()) { possible = false; break; }
                prevDensity = densities.get(lo);
                idx.put(color, lo + 1);
            }

            System.out.println(possible ? "Yes" : "No");
        }
    }
}

