/*
 * The statement provided is incomplete, so this solution implements the natural
 * interpretation of the described task:
 *
 * - There are prepared colored liquids, each having a color and a density.
 * - A requested drink specifies a sequence of color layers from bottom to top.
 * - Liquids cannot be mixed.
 * - In a valid layered drink, each upper layer must have strictly smaller density
 *   than the layer directly below it.
 *
 * Therefore, a request is feasible iff we can choose one prepared liquid for each
 * requested color such that densities strictly decrease from bottom to top.
 *
 * Input format assumed:
 *   N M
 *   color_1 density_1
 *   ...
 *   color_N density_N
 *   k_1 c_1 c_2 ... c_k1
 *   ...
 *   k_M ...
 *
 * Output:
 *   For each request, print "Yes" if feasible, otherwise "No".
 *
 * This is solved by:
 * - Compressing densities.
 * - For each color, storing the sorted list of densities available for that color.
 * - For each query, greedily choosing the largest possible density for each layer
 *   that is still less than the previous chosen density.
 *
 * If your judge uses a slightly different textual format, only the parser would
 * need adjustment; the core algorithm remains the same.
 */

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static boolean canMake(List<Long> dens, List<String> req, Map<String, long[]> map) {
        long prev = Long.MAX_VALUE;
        for (String color : req) {
            long[] arr = map.get(color);
            if (arr == null || arr.length == 0) return false;
            int idx = lowerBound(arr, prev) - 1; // largest density < prev
            if (idx < 0) return false;
            prev = arr[idx];
        }
        return true;
    }

    static int lowerBound(long[] arr, long x) {
        int l = 0, r = arr.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m] >= x) r = m;
            else l = m + 1;
        }
        return l;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.next();
        if (first == null) return;

        int N = Integer.parseInt(first);
        int M = fs.nextInt();

        Map<String, ArrayList<Long>> temp = new HashMap<>();
        for (int i = 0; i < N; i++) {
            String color = fs.next();
            long density = fs.nextLong();
            temp.computeIfAbsent(color, k -> new ArrayList<>()).add(density);
        }

        Map<String, long[]> liquids = new HashMap<>();
        for (Map.Entry<String, ArrayList<Long>> e : temp.entrySet()) {
            ArrayList<Long> list = e.getValue();
            Collections.sort(list);
            long[] arr = new long[list.size()];
            for (int i = 0; i < list.size(); i++) arr[i] = list.get(i);
            liquids.put(e.getKey(), arr);
        }

        StringBuilder out = new StringBuilder();
        for (int q = 0; q < M; q++) {
            int k = fs.nextInt();
            List<String> req = new ArrayList<>(k);
            for (int i = 0; i < k; i++) req.add(fs.next());
            out.append(canMake(null, req, liquids) ? "Yes" : "No").append('\n');
        }

        System.out.print(out.toString());
    }
}

