#define MAX_COLORS 100000

typedef struct Node {
    int density;
    struct Node *next;
} Node;

Node *color_list[MAX_COLORS];
int color_used[MAX_COLORS];

void insert_sorted(int color, int density) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->density = density;
    new_node->next = NULL;

    if (color_list[color] == NULL || color_list[color]->density > density) {
        new_node->next = color_list[color];
        color_list[color] = new_node;
        return;
    }

    Node *curr = color_list[color];
    while (curr->next != NULL && curr->next->density < density) {
        curr = curr->next;
    }
    new_node->next = curr->next;
    curr->next = new_node;
}

int find_and_remove(int color, int min_density) {
    Node *curr = color_list[color];
    Node *prev = NULL;

    while (curr != NULL && curr->density <= min_density) {
        prev = curr;
        curr = curr->next;
    }

    if (curr == NULL) return -1;

    int val = curr->density;
    if (prev == NULL) {
        color_list[color] = curr->next;
    } else {
        prev->next = curr->next;
    }
    free(curr);
    return val;
}

int main() {
    int N;
    scanf("%d", &N);

    for (int i = 0; i < MAX_COLORS; i++) {
        color_list[i] = NULL;
    }

    for (int i = 0; i < N; i++) {
        int c, d;
        scanf("%d %d", &c, &d);
        insert_sorted(c, d);
    }

    int K;
    scanf("%d", &K);
    int layers[K];
    for (int i = 0; i < K; i++) {
        scanf("%d", &layers[i]);
    }

    int prev_density = -1;
    for (int i = 0; i < K; i++) {
        int col = layers[i];
        int chosen = find_and_remove(col, prev_density);
        if (chosen == -1) {
            printf("No\n");
            // free remaining memory (omitted for brevity)
            return 0;
        }
        prev_density = chosen;
    }

    printf("Yes\n");
    // free remaining memory (omitted for brevity)
    return 0;
}

