#define MAXN 200005
#define MAXC 64

typedef struct {
    char color[MAXC];
    int density;
} Liquid;

typedef struct {
    char color[MAXC];
    int minD, maxD;
    int used;
} ColorRange;

static Liquid liquids[MAXN];
static ColorRange ranges[MAXN];
static int rangeCount = 0;

int cmpLiquid(const void *a, const void *b) {
    const Liquid *x = (const Liquid *)a;
    const Liquid *y = (const Liquid *)b;
    if (x->density != y->density) return x->density - y->density;
    return strcmp(x->color, y->color);
}

int findColorRange(const char *color) {
    for (int i = 0; i < rangeCount; i++) {
        if (strcmp(ranges[i].color, color) == 0) return i;
    }
    return -1;
}

int main(void) {
    int n, m;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%s %d", liquids[i].color, &liquids[i].density);
        int idx = findColorRange(liquids[i].color);
        if (idx == -1) {
            idx = rangeCount++;
            strcpy(ranges[idx].color, liquids[i].color);
            ranges[idx].minD = ranges[idx].maxD = liquids[i].density;
            ranges[idx].used = 0;
        } else {
            if (liquids[i].density < ranges[idx].minD) ranges[idx].minD = liquids[i].density;
            if (liquids[i].density > ranges[idx].maxD) ranges[idx].maxD = liquids[i].density;
        }
    }

    if (scanf("%d", &m) != 1) return 0;

    char prevColor[MAXC], curColor[MAXC];
    int prevIdx, curIdx;
    int possible = 1;

    if (m > 0) {
        scanf("%s", prevColor);
        prevIdx = findColorRange(prevColor);
        if (prevIdx == -1) possible = 0;
    }

    for (int i = 1; i < m; i++) {
        scanf("%s", curColor);
        curIdx = findColorRange(curColor);
        if (curIdx == -1) {
            possible = 0;
            continue;
        }
        if (possible) {
            /* Assuming input lists layers from bottom to top:
               upper density must be strictly less than lower density. */
            if (!(ranges[curIdx].minD < ranges[prevIdx].maxD)) {
                possible = 0;
            }
        }
        prevIdx = curIdx;
    }

    printf("%s\n", possible ? "Yes" : "No");
    return 0;
}

